CREATE OR ALTER PROCEDURE [dbo].[uspDeliveryOrder_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @OrderId UNIQUEIDENTIFIER = NULL
	, @CustomerId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @CustomerDeliveryLocationId UNIQUEIDENTIFIER = NULL
	, @DeliveryRouteId UNIQUEIDENTIFIER = NULL
	, @DeliveryNumber NVARCHAR(MAX) = NULL
	, @PlannedDeliveryTime DATETIME2 = NULL
	, @ActualDeliveryTime DATETIME2 = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[OrderId]
			, t.[CustomerId]
			, t.[DeliveryDate]
			, t.[Status]
			, t.[CustomerDeliveryLocationId]
			, t.[DeliveryRouteId]
			, t.[DeliveryNumber]
			, t.[PlannedDeliveryTime]
			, t.[ActualDeliveryTime]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[DeliveryOrder] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[DeliveryNumber] LIKE CONCAT('%', @SearchText, '%'))
			AND (@OrderId IS NULL OR t.[OrderId] = @OrderId)
			AND (@CustomerId IS NULL OR t.[CustomerId] = @CustomerId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@CustomerDeliveryLocationId IS NULL OR t.[CustomerDeliveryLocationId] = @CustomerDeliveryLocationId)
			AND (@DeliveryRouteId IS NULL OR t.[DeliveryRouteId] = @DeliveryRouteId)
			AND (ISNULL(@DeliveryNumber, '') = '' OR t.[DeliveryNumber] LIKE CONCAT('%', @DeliveryNumber, '%'))
			AND (@PlannedDeliveryTime IS NULL OR t.[PlannedDeliveryTime] = @PlannedDeliveryTime)
			AND (@ActualDeliveryTime IS NULL OR t.[ActualDeliveryTime] = @ActualDeliveryTime)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderId' THEN r.[OrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderId' THEN r.[OrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerId' THEN r.[CustomerId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerId' THEN r.[CustomerId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryDate' THEN r.[DeliveryDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryDate' THEN r.[DeliveryDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerDeliveryLocationId' THEN r.[CustomerDeliveryLocationId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerDeliveryLocationId' THEN r.[CustomerDeliveryLocationId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryRouteId' THEN r.[DeliveryRouteId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryRouteId' THEN r.[DeliveryRouteId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryNumber' THEN r.[DeliveryNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryNumber' THEN r.[DeliveryNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'plannedDeliveryTime' THEN r.[PlannedDeliveryTime] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'plannedDeliveryTime' THEN r.[PlannedDeliveryTime] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'actualDeliveryTime' THEN r.[ActualDeliveryTime] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'actualDeliveryTime' THEN r.[ActualDeliveryTime] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
